    """Return True iff `order` is a valid LexBFS ordering of `graph`.

    Uses the (LB) 4-point property: for all positions a < b < c with
    ac in E and ab not in E, exists d < a with db in E and dc not in E.

    Equivalent witness form: for each a, let N_a = {d < a : da not in E}.
    The property holds iff no b > a with ab not in E is adjacent to all
    of N_a.
    """
    n = len(order)
    adj = graph
    for a in range(n):
        va = order[a]
        # N_a: earlier vertices not adjacent to va
        N_a = [order[d] for d in range(a) if not adj[va][order[d]]]
        if not N_a:
            continue
        for b in range(a + 1, n):
            vb = order[b]
            if adj[va][vb]:
                continue  # ab in E: no constraint
            # b must NOT be adjacent to every vertex in N_a
            for vd in N_a:
